CREATE TEMPORARY VIEW search_algo_log_raw_${grass_region_without_quote} AS
    select  LOWER(TRIM(query)) as keyword
           ,request_params.request_items as items
    from    search_data.dwd_extracted_data_from_sample_dump_1h
    where   dt = ${local_date} AND country IN (${grass_region});

--sql_divide_splitter--

CREATE TEMPORARY VIEW search_algo_log_item_exploded_${grass_region_without_quote} AS
    select   keyword
            ,item.item_id as item_id
            ,item.recall_types as queues
    from search_algo_log_raw_${grass_region_without_quote}
    lateral view explode(items) as item;

--sql_divide_splitter--

CREATE TEMPORARY VIEW search_algo_log_queue_exploded_${grass_region_without_quote} AS
    select keyword,
           queue_id,
           item_id
    from search_algo_log_item_exploded_${grass_region_without_quote}
    lateral view explode(queues) as queue_id;

--sql_divide_splitter--

CREATE TEMPORARY VIEW search_algo_log_agg_${grass_region_without_quote} AS
    select keyword,
           queue_id,
           count(distinct item_id) as ranking_items
    from search_algo_log_queue_exploded_${grass_region_without_quote}
    where item_id > 0 and keyword is not null and queue_id >= 0
    group by 1,2
    having count(distinct item_id) >= 5;

--sql_divide_splitter--

CREATE TEMPORARY VIEW search_tracking_raw_${grass_region_without_quote} AS
SELECT LOWER(TRIM(keyword)) as keyword
       ,queue_id
       ,user_id
       ,request_id
       ,item_id
       ,imp_time
       ,clk_time
       ,order_create_time
       ,gmv_usd
FROM srdi_mart.dwd_fp_search_base_1d
LATERAL VIEW EXPLODE(rule_ids) as queue_id
WHERE country IN (${grass_region}) AND dt = ${local_date} and is_ads = false;

--sql_divide_splitter--

CREATE TEMPORARY VIEW search_tracking_${grass_region_without_quote} AS
SELECT  keyword
       ,queue_id
       ,user_id
       ,request_id
       ,item_id
       ,max(case when imp_time is not null then 1 else 0 end) as is_imp
       ,max(case when clk_time is not null then 1 else 0 end) as is_clk
       ,max(case when order_create_time is not null then 1 else 0 end) as is_order
       ,sum(ifnull(gmv_usd,0)) as gmv_usd
FROM search_tracking_raw_${grass_region_without_quote}
group by 1,2,3,4,5
having max(case when imp_time is not null then 1 else 0 end) > 0;

--sql_divide_splitter--

CREATE TEMPORARY VIEW search_tracking_1d_${grass_region_without_quote} AS
SELECT  keyword
       ,queue_id
       ,count(distinct case when is_imp > 0 then item_id else null end) as imp_items
       ,sum(case when is_imp > 0 then 1 else 0 end) as imp_pv
       ,count(distinct case when is_imp > 0 then user_id else null end) as imp_uv
       ,count(distinct case when is_clk > 0 then item_id else null end) as click_items
       ,sum(case when is_clk > 0 then 1 else 0 end) as click_pv
       ,count(distinct case when is_clk > 0 then user_id else null end) as click_uv
       ,sum(case when is_clk > 0 then 1 else 0 end)/sum(case when is_imp > 0 then 1 else 0 end) as ctr_pv
       ,count(distinct case when is_order > 0 then item_id else null end) as order_items
       ,sum(case when is_order > 0 then 1 else 0 end) as order_num
       ,sum(gmv_usd) as order_gmv
       ,count(distinct case when is_order > 0 then user_id else null end) as order_uv
FROM search_tracking_${grass_region_without_quote}
group by 1,2;

--sql_divide_splitter--

CREATE TEMPORARY VIEW search_tracking_7d_raw_${grass_region_without_quote} AS
SELECT LOWER(TRIM(keyword)) as keyword
       ,queue_id
       ,item_id
       ,order_id
       ,gmv_usd
       ,user_id
FROM srdi_mart.dwd_fp_search_base_1d
LATERAL VIEW EXPLODE(rule_ids) as queue_id
WHERE country IN (${grass_region}) and is_ads = false and order_id is not null
      AND dt BETWEEN DATE_SUB(${local_date}, 7) AND DATE_SUB(${local_date}, 1);

--sql_divide_splitter--

CREATE TEMPORARY VIEW search_tracking_7d_${grass_region_without_quote} AS
SELECT  keyword
       ,queue_id
       ,count(distinct item_id) as order_items_7d
       ,count(distinct order_id) as order_num_7d
       ,sum(gmv_usd) as order_gmv_7d
       ,count(distinct user_id) as order_uv_7d
FROM search_tracking_7d_raw_${grass_region_without_quote}
group by 1,2;

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_keyword_queue_metrics_1d
PARTITION (
     grass_region = ${grass_region}
    ,local_date = ${local_date}
)
select a.queue_id
      ,a.keyword
      ,a.ranking_items
      ,b.imp_items
      ,b.imp_pv
      ,b.imp_uv
      ,b.click_items
      ,b.click_pv
      ,b.click_uv
      ,b.ctr_pv
      ,b.order_items
      ,b.order_num
      ,b.order_gmv
      ,b.order_uv
      ,c.order_items_7d
      ,c.order_num_7d
      ,c.order_gmv_7d
      ,c.order_uv_7d
from search_algo_log_agg_${grass_region_without_quote} a
left join search_tracking_1d_${grass_region_without_quote} b
on a.keyword = b.keyword and a.queue_id = b.queue_id
left join search_tracking_7d_${grass_region_without_quote} c
on a.keyword = c.keyword and a.queue_id = c.queue_id
